import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class TransactionMonitor {

    // Stores timestamps of transactions for each user
    private Map<String, List<Long>> userTransactions = new HashMap<>(); 

    /**
     * Detects if a user has made more than 'maxTransactions' in 'timeWindowSeconds'.
     * This method is called upon each new transaction for a user.
     * 
     * @param userId The ID of the user.
     * @param transactionTimestampMillis The timestamp of the current transaction in milliseconds.
     * @param maxTransactions The maximum allowed transactions within the window.
     * @param timeWindowSeconds The duration of the time window in seconds.
     * @return true if the user's activity is considered fraudulent, false otherwise.
     */
    public boolean checkFraudulentActivity(String userId, long transactionTimestampMillis, int maxTransactions, int timeWindowSeconds) {
        List<Long> transactions = userTransactions.getOrDefault(userId, new ArrayList<>());
        transactions.add(transactionTimestampMillis);

        // Remove old transactions outside the window
        transactions.removeIf(txTime -> (transactionTimestampMillis - txTime) / 1000 > timeWindowSeconds);

        userTransactions.put(userId, transactions); 

        return transactions.size() > maxTransactions;
    }
}
